import subprocess, json, sys

def run(raw):
    p = subprocess.run([sys.executable,'-I','/app/submission/entry.py'], input=raw.encode() if isinstance(raw,str) else raw, capture_output=True)
    try:
        return json.loads(p.stdout.decode())
    except Exception as e:
        return {'_raw': p.stdout.decode(), '_err': p.stderr.decode()}

def cfg(**kw):
    base=dict(early=False,overlap="reject",buffer_packets=4,idle_ms=0,
              max_streams_bidi=100,max_streams_uni=100,max_stream_data=1000000,
              max_data=1000000000,crypto_limit=1000000,
              sent={"I":[],"H":[],"A":[]})
    base.update(kw); return base

def req(traces): return {"version":1,"traces":traces}
def tr(tid,config,events): return {"id":tid,"config":config,"events":events}

# ---- invalid inputs ----
invalids = {
 "dupkey": '{"version":1,"version":1,"traces":[]}',
 "float": '{"version":1,"traces":[]} x' ,
 "trailing": '{"version":1,"traces":[]}{}',
 "floatval": '{"version":1.0,"traces":[]}',
 "nan": '{"version":1,"traces":[]}',
 "badutf": b'\xff\xfe',
 "unknownkey": '{"version":1,"traces":[],"x":1}',
 "badlevel": json.dumps(req([tr("a",cfg(),[{"t":0,"op":"key","level":"Q","action":"install"}])])),
 "truenum": json.dumps({"version":True,"traces":[]}),
}
for name,raw in invalids.items():
    o=run(raw)
    print(name, o.get('error') if isinstance(o,dict) else o)
